recursion.cpp:
#include <iostream>
using namespace std;

int fact(int n) {
    return n == 0 ? 1 : n * fact(n - 1);
}

int main() {
    cout << fact(5);
    return 0;
}

recursion.java:
class Main {
    static int fact(int n) {
        if (n == 0) {
            return 1;
        } else {
            return n * fact(n - 1);
        }
    }

    public static void main(String[] args) {
        System.out.println(fact(5));
    }
}

