dynamic_programming.cpp:
#include <iostream>
using namespace std;

int main() {
    int dp[6] = {0, 1};

    for (int i = 2; i < 6; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }

    cout << dp[5];
    return 0;
}

dynamic_programming.java:
class Main {
    public static void main(String[] args) {
        int[] dp = new int[6];
        dp[1] = 1;

        for (int i = 2; i < 6; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }

        System.out.println(dp[5]);
    }
}

